toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #fff;
    border-bottom: 1px solid #1e1f22;
}

.channel-list {
    list-style: none;
    padding: 8px;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 12px;
    border-radius: 4px;
    cursor: pointer;
    margin-bottom: 2px;
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 8px;
    top: 50%;
    transform: translateY(-50%);
    background: #f23f43;
    color: #fff;
    border-radius: 10px;
    padding: 2px 6px;
    font-size: 0.7rem;
    font-weight: 700;
    min-width: 18px;
    text-align: center;
}

/* Main Panel */
.main-panel {
    flex: 1;
    display: flex;
    min-width: 0;
}

.main-panel.with-thread {
    width: 55%;
    flex: none;
}

.main-panel.full-width {
    width: 80%;
    flex: 1;
}

/* Message Area */
.message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    background: #313338;
    color: #dbdee1;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #949ba4;
    font-size: 0.85rem;
}

.message-item {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
}

.message-item:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
}

.message-time {
    font-size: 0.75rem;
    color: #949ba4;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

.reactions-row {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dbdee1;
}

.reaction-badge:hover {
    border-color: #5865f2;
    background: #373a40;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 8px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
    font-size: 0.9rem;
}

.action-btn:hover {
    background: #383a40;
}

.emoji-picker {
    position: absolute;
    top: -44px;
    right: 8px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    z-index: 10;
}

.emoji-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 4px;
}

.emoji-btn:hover {
    background: #383a40;
}

/* Message Input */
.message-input-area,
.thread-input-area {
    padding: 12px 16px;
    border-top: 1px solid #3f4147;
    display: flex;
    gap: 8px;
    flex-shrink: 0;
}

.message-textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #dbdee1;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
}

.message-textarea::placeholder {
    color: #6d6f78;
}

.message-textarea:focus {
    outline: none;
    box-shadow: 0 0 0 1px #5865f2;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 16px;
    cursor: pointer;
    font-weight: 600;
    font-size: 0.85rem;
    align-self: flex-end;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2b2d31;
    color: #dbdee1;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

.thread-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #383a40;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    margin-top: 4px;
    font-size: 0.85rem;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.thread-reply {
    padding: 6px 0;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

