+    font-size: 0.85rem;
+}
+
+.message-item {
+    padding: 8px 12px;
+    border-radius: 4px;
+    position: relative;
+}
+
+.message-item:hover {
+    background: #2e3035;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 4px;
+}
+
+.message-author {
+    font-weight: 600;
+    color: #fff;
+    font-size: 0.95rem;
+}
+
+.message-time {
+    font-size: 0.75rem;
+    color: #949ba4;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+    word-wrap: break-word;
+}
+
+.reactions-row {
+    display: flex;
+    gap: 4px;
+    margin-top: 6px;
+    flex-wrap: wrap;
+}
+
+.reaction-badge {
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 4px;
+    padding: 2px 8px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    color: #dbdee1;
+}
+
+.reaction-badge:hover {
+    border-color: #5865f2;
+    background: #373a40;
+}
+
+.thread-link {
+    background: none;
+    border: none;
+    color: #00a8fc;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    margin-top: 4px;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+.message-actions {
+    position: absolute;
+    top: -12px;
+    right: 8px;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 4px;
+    display: flex;
+    gap: 2px;
+    padding: 2px;
+}
+
+.action-btn {
+    background: none;
+    border: none;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 3px;
+    font-size: 0.9rem;
+}
+
+.action-btn:hover {
+    background: #383a40;
+}
+
+.emoji-picker {
+    position: absolute;
+    top: -44px;
+    right: 8px;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 6px;
+    padding: 6px;
+    display: flex;
+    gap: 4px;
+    z-index: 10;
+}
+
+.emoji-btn {
+    background: none;
+    border: none;
+    cursor: pointer;
+    font-size: 1.2rem;
+    padding: 4px;
+    border-radius: 4px;
+}
+
+.emoji-btn:hover {
+    background: #383a40;
+}
+
+/* Message Input */
+.message-input-area,
+.thread-input-area {
+    padding: 12px 16px;
+    border-top: 1px solid #3f4147;
+    display: flex;
+    gap: 8px;
+    flex-shrink: 0;
+}
+
+.message-textarea {
+    flex: 1;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 12px;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+}
+
+.message-textarea::placeholder {
+    color: #6d6f78;
+}
+
+.message-textarea:focus {
+    outline: none;
+    box-shadow: 0 0 0 1px #5865f2;
+}
+
+.send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 8px 16px;
+    cursor: pointer;
+    font-weight: 600;
+    font-size: 0.85rem;
+    align-self: flex-end;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2b2d31;
+    color: #dbdee1;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #1e1f22;
+}
+
+.thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+}
+
+.thread-header h3 {
+    margin: 0;
+    color: #fff;
+    font-size: 1rem;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    cursor: pointer;
+    font-size: 1.2rem;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #383a40;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+    background: #232428;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    margin-top: 4px;
+    font-size: 0.85rem;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 12px;
+}
+
+.thread-reply {
+    padding: 6px 0;
+}
+
+.thread-reply .message-content {
+    font-size: 0.85rem;
+}
+

